@PostMapping("/${cursor}")
	public ResponseEntity<Result<?>> doPost(@RequestBody Map<String,String> req,HttpSession sess){
		System.out.println("/${value} POST");
		req.forEach((paramName, paramValue) -> {
		    System.out.println("- "+paramName + " [" + paramValue + "]");
		});
		try {
			return ResponseEntity.ok(new Result<>(1,""));
		} catch(Exception e) {
			return ResponseEntity.ok(new Result<>(-1,e.getMessage()));
		}
	}
